cmd:
for f in \
/mnt/local-analysis/workspace-hub/.claude/skills/ai/optimization/model-selection/SKILL.md \
/mnt/local-analysis/workspace-hub/.claude/skills/ai/optimization/usage-optimization/SKILL.md \
/mnt/local-analysis/workspace-hub/.claude/skills/business/product/product-roadmap/SKILL.md \
/mnt/local-analysis/workspace-hub/.claude/skills/development/code-reviewer/SKILL.md \
/mnt/local-analysis/workspace-hub/.claude/skills/data/energy/field-analyzer/SKILL.md; do
  echo "===== $f";
  sed -n '1,60p' "$f";
  echo;
done

set -e
f=.claude/skills/data/energy/bsee-data-extractor/SKILL.md
git -C /mnt/local-analysis/workspace-hub show HEAD:$f > /mnt/local-analysis/workspace-hub/$f
# keep first side of merge markers
awk 'BEGIN{in=0;keep=1}
/^<<<<<<< /{in=1;keep=1;next}
/^=======$/{if(in){keep=0;next}}
/^>>>>>>> /{if(in){in=0;keep=1;next}}
{if(!in || keep) print}
' /mnt/local-analysis/workspace-hub/$f > /tmp/bsee_skill_fixed.md
mv /tmp/bsee_skill_fixed.md /mnt/local-analysis/workspace-hub/$f
rg -n "<<<<<<<|=======|>>>>>>>" /mnt/local-analysis/workspace-hub/$f || true
sed -n '1,24p' /mnt/local-analysis/workspace-hub/$f

set -e
f=.claude/skills/data/energy/bsee-data-extractor/SKILL.md
git -C /mnt/local-analysis/workspace-hub show HEAD:$f > /mnt/local-analysis/workspace-hub/$f
awk 'BEGIN{in_conflict=0;keep=1}
/^<<<<<<< /{in_conflict=1;keep=1;next}
/^=======$/{if(in_conflict){keep=0;next}}
/^>>>>>>> /{if(in_conflict){in_conflict=0;keep=1;next}}
{if(!in_conflict || keep) print}
' /mnt/local-analysis/workspace-hub/$f > /tmp/bsee_skill_fixed.md
mv /tmp/bsee_skill_fixed.md /mnt/local-analysis/workspace-hub/$f
rg -n "<<<<<<<|=======|>>>>>>>" /mnt/local-analysis/workspace-hub/$f || echo cleaned
sed -n '1,24p' /mnt/local-analysis/workspace-hub/$f
